      SUBROUTINE ALTER(CHANGE)CC     SUBROUTINE ALTER USES CHANGE DATA IN CA(*,1) AND MODIFIES THE DATA ARRAY.CC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'BROAD.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10D.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM39C.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'STEPT1.CIN'CC     LOCAL VARIABLESC      CHARACTER*10     CHOUT(20)      INTEGER          VARY      REAL             CHANGE(NPVAR+1)      REAL             LIMIT      EXTERNAL         IDATACC--------------------------------------------------------C     CHANGE VARIED PARAMETERS TO NEW VALUESC      CALL INITLC      DO 100 IRU = 1, 2      IHIGH = 0      DO 90 NUM = 1, NEL      I = ISTOR(NUM)      IF (I .LT. IHIGH) GO TO 90      IHIGH = MAX0(I,IHIGH)      TYPE = IDATA(I)      IF (TYPE .LE. 0 .OR. TYPE .GE. 50) GO TO 90      CALL SKETCH(NUM)      IF (TYPE .EQ. 10) GO TO 90      IF (TYPE .EQ. 39) GO TO 80      NVT = NV(TYPE)      IF (NVT .LT. 1) GO TO 90      DO 60 J = 1, NVT      IPT = IPTOJ(J)      IF (IPT .EQ. 0) GO TO 60      IPLUSJ = I + IPT      VARY = TIE(IPLUSJ)      IF (VARY .EQ. 0 .OR. VARY .GE. 99) GO TO 60      IVARY = IABS(VARY)      IF (IVARY .GT. NV1) GO TO 60      SIG = SIGNF(FLOAT(VARY))      X2 = DATA(IPLUSJ) + SIG*CHANGE(IVARY+1)      IF (IRU .EQ. 2) GO TO 50CC     LOWER LIMIT TESTC      SI = LIMIT(TYPE,J,2)      IF (SI .EQ. 0.0) GO TO 30      SI = LIMIT(TYPE,J,1)      IF (X2 .GE. SI) GO TO 30      X2 = AMAX1(X2,SI)      GO TO 40CC     UPPER LIMIT TESTC   30 SI = LIMIT(TYPE,J,4)      IF (SI .EQ. 0.0) GO TO 60      SI = LIMIT(TYPE,J,3)      IF (X2 .LE. SI) GO TO 60      X2 = AMIN1(X2,SI)C   40 CHANGE(IVARY+1) = (X2 - DATA(IPLUSJ))*SIG      IF (IVARY .GT. NPVAR + 1 .OR. IVARY .LT. 0) THEN        WRITE (NOUT,9008) 9008   FORMAT (' IN ALTER, IVARY = ',I8)        FLUSHL = .TRUE.        GO TO 200      ENDIF      GO TO 60C   50 DATA(IPLUSJ) = X2      IF (IPLUSJ .GT. IDALIM .OR. IPLUSJ .LE. 0) THEN        WRITE (NOUT,9009) 9009   FORMAT (' IN ALTER, IPLUSJ = ',I8)        FLUSHL = .TRUE.        GO TO 200      ENDIF   60 CONTINUE      GO TO 90C   80 TYPEL = INT(DATA(I+1))      NPARL = INT(DATA(I+2))      IF (IPTOJ(3) .NE. 0) THEN        IPT = IPTOJ(3)        LTYPE = 1        DPARL = DATA(I+IPT)        CALL LIMSET      ENDIF      IF (IPTOJ(4) .NE. 0) THEN        IPT = IPTOJ(4)        LTYPE = 2        DPARL = DATA(I+IPT)        CALL LIMSET      ENDIF      IF (IPTOJ(5) .NE. 0) THEN        IPT = IPTOJ(5)        LTYPE = 1        DPARL = DATA(I+IPT)        DPARL = - ABS(DPARL)        CALL LIMSET        LTYPE = 2        DPARL = ABS(DPARL)        CALL LIMSET      ENDIFC   90 CONTINUE  100 CONTINUECC     PRINT OUT CHANGES APPLIEDC      IF (.NOT. ONLY .AND. .NOT. (LSTEP .AND. .NOT. BROAD)) THEN        DO 110 J = 1, NV1        CHAN = CHANGE(J+1)        ACHAN = ABS(CHAN)        IF (ACHAN .GE. 0.001 .AND. ACHAN .LT. 10000.0) THEN          WRITE (CHOUT(J),1001) CHAN        ELSE          WRITE (CHOUT(J),1002) CHAN        ENDIF  110   CONTINUE        WRITE (NOUT,1000) EPS, CA(1,1), (CHOUT(J), J = 1, NV1)      ENDIFC  200 RETURNC 1000 FORMAT (1X,E12.5,1X,'(',E12.5,')',10A10,/(28X,10A10)) 1001 FORMAT (F10.4) 1002 FORMAT (E10.2)      END